/// <summary>
/// Get WareHouse address By recevingdock role
/// </summary>
/// <param name = "_inventLocationRecId">Location RecId</param>
/// <param name = "_roleRecId">Role Recid</param>
/// <param name = "_type">LogisticsElectronicAddressMethodType</param>
/// <returns>Locator</returns>
private LogisticsEntityPostalAddressView getWareHousePrimaryAddress(RefRecId _inventLocationRecId)
{
    LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;

    select firstonly Address from logisticsEntityPostalAddressView
        where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
        && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.IsPrimary == NoYes::Yes;

    return logisticsEntityPostalAddressView;
}

/// <summary>
/// Gets the lodgement details for the updated excise information table.
/// </summary>
/// <param name = "_metExciseInformationTable">_metExciseInformationTable buffer</param>
/// <returns>Returns the concatenated lodgement details.</returns>
private METLodgement getMetLodgement(ItemId _itemId, InventSiteId _siteId, Qty _salesLineQty)
{
    METLodgement metLodgement;

    METExciseLodgementUpdateService service = new METExciseLodgementUpdateService();
    METExciseLodgementUpdateContract contract = new METExciseLodgementUpdateContract();

    contract.parmReferenceId(InventTransType::Sales);
    contract.parmItemId(_itemId);
    contract.parmSiteId(_siteId);

    service.runExciseLodgementUpdateActual(contract, salesTable.SalesId);
    metLodgement = service.getMetLodgement();

    return metLodgement;
}

private void prepareRecordListTmp(SalesLine _salesLine, InventTable _inventTable, METInventTable _metInventTable, METTariffItemCodeBase _tariffCodeBase, METLodgement _lodgement)
{
    const str defaultUOM = 'EA';

    METExciseRegisterEntry exciseRegister;
    METSalesLine metSalesLine;

    if (_lodgement)
    {
        // Find the matching Sales line
        select firstonly metSalesLine
            where metSalesLine.SalesLine == _salesLine.RecId;

        if (metSalesLine.RecId)
        {
            ttsbegin;
            // Update existing record
            metSalesLine.selectForUpdate(true);
            metSalesLine.Lodgement = _lodgement;
            metSalesLine.update();
            ttscommit;
        }
        else
        {
            // Insert new record
            metSalesLine.SalesLine = _salesLine.RecId;
            metSalesLine.Lodgement = _lodgement;
            metSalesLine.insert();
        }
    }

    InventSiteId  siteId = _salesLine.inventDim().InventSiteId;

    //select TIUV, DutyRateReceived from exciseRegister
    //    where exciseRegister.SiteId == siteId
    //    && exciseRegister.ItemId == _salesLine.ItemId
    //    && exciseRegister.Lodgement == line.BondMark;

    select TIUV, DutyRateReceived from exciseRegister
        where exciseRegister.Lodgement == _lodgement;

    METPurchaseWMSFactor purchaseWMSFactor = UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(_salesLine.SalesUnit).RecId, UnitOfMeasure::findBySymbol(defaultUOM).RecId, EcoResProduct::findByProductNumber(_salesLine.ItemId).RecId).Factor;
    line.BottlesSupplied = abs(purchaseWMSFactor * _salesLine.SalesQty);
    line.ItemId = _salesLine.ItemId;
    line.ItemDescription = _inventTable.productName(SystemParameters::getSystemLanguageId());
    line.BottleSize = _metInventTable.BottleSize;
    line.PackQty = _metInventTable.ItemPack;
    line.Strength = _metInventTable.AlcoholContent;
    line.SalesUoM = _salesLine.SalesUnit;
    line.Quantity = _salesLine.SalesQty;
    line.LitresOfAlcoholCalculated = _metInventTable.BottleSize * (_metInventTable.AlcoholContent/100) * _metInventTable.ItemPack;

    line.ValueTIU = exciseRegister.TIUV;
    line.TariffItem = _tariffCodeBase.TariffItem;
    line.CountryOfOrigin = _metInventTable.CountryCode;
    line.StatCode = _metInventTable.statcode();
    line.ValueDuty = METExciseSiteDutySetup::find(siteId, _salesLine.ItemId).DutyTotal;
    line.InvoiceAccount = salesTable.InvoiceAccount;
    line.SalesId = salesTable.SalesId;
    line.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    line.ContinuingPermissionHeaderGuidStr = headerReportGuid;
    recordInsertList.add(line);
}
